// حالات التنقل
let currentView = 'faculties'; // 'faculties', 'departments', 'levels', 'terms', 'books'
let selectedFaculty = null;
let selectedDepartment = null;
let selectedLevel = null;
let selectedTerm = null;

const appContainer = document.getElementById('appContainer');
const breadcrumbBar = document.getElementById('breadcrumbBar');
const globalSearch = document.getElementById('globalSearch');
const themeToggle = document.getElementById('themeToggle');

// دالة العرض الرئيسية (Router)
function renderApp() {
    updateBreadcrumb();
    appContainer.innerHTML = '';

    if (currentView === 'faculties') {
        renderFacultiesView(universityDatabase);
    } else if (currentView === 'departments') {
        renderDepartmentsView(selectedFaculty);
    } else if (currentView === 'levels') {
        renderLevelsView(selectedDepartment);
    } else if (currentView === 'terms') {
        renderTermsView(selectedLevel);
    } else if (currentView === 'books') {
        renderBooksView(selectedTerm);
    }
}

// 1. عرض الكليات (الشاشة الرئيسية)
function renderFacultiesView(data) {
    appContainer.innerHTML = `
        <div class="section-header">
            <h2>كليات جامعة الحديدة الرئيسية</h2>
            <p>اختر الكلية المطلوبة لاستعراض الأقسام والتخصصات الأكاديمية</p>
        </div>
        <div class="cards-grid" id="gridContent"></div>
    `;
    const grid = document.getElementById('gridContent');
    data.forEach(fac => {
        const card = document.createElement('div');
        card.className = 'interactive-card';
        card.innerHTML = `
            <div class="card-icon"><i class="fa-solid ${fac.icon}"></i></div>
            <h3>${fac.name}</h3>
            <span>${fac.departments.length} أقسام رئيسية</span>
            <button class="card-btn">دخول الكلية <i class="fa-solid fa-arrow-left"></i></button>
        `;
        card.addEventListener('click', () => {
            selectedFaculty = fac;
            currentView = 'departments';
            renderApp();
        });
        grid.appendChild(card);
    });
}

// 2. عرض الأقسام
function renderDepartmentsView(faculty) {
    appContainer.innerHTML = `
        <div class="section-header">
            <h2>${faculty.name}</h2>
            <p>اختر القسم العلمي للوصول إلى المستويات الدراسية</p>
        </div>
        <div class="cards-grid" id="gridContent"></div>
    `;
    const grid = document.getElementById('gridContent');
    faculty.departments.forEach(dept => {
        const card = document.createElement('div');
        card.className = 'interactive-card';
        card.innerHTML = `
            <div class="card-icon"><i class="fa-solid fa-book-open-reader"></i></div>
            <h3>${dept.name}</h3>
            <span>4 مستويات دراسية</span>
            <button class="card-btn">عرض الأقسام والمستويات <i class="fa-solid fa-arrow-left"></i></button>
        `;
        card.addEventListener('click', () => {
            selectedDepartment = dept;
            currentView = 'levels';
            renderApp();
        });
        grid.appendChild(card);
    });
}

// 3. عرض المستويات (من الأول للرابع)
function renderLevelsView(dept) {
    appContainer.innerHTML = `
        <div class="section-header">
            <h2>${dept.name}</h2>
            <p>اختر المستوى الدراسي (من الأول إلى الرابع)</p>
        </div>
        <div class="cards-grid" id="gridContent"></div>
    `;
    const grid = document.getElementById('gridContent');
    dept.levels.forEach(lvl => {
        const card = document.createElement('div');
        card.className = 'interactive-card';
        card.innerHTML = `
            <div class="card-icon"><i class="fa-solid fa-layer-group"></i></div>
            <h3>${lvl.name}</h3>
            <span>يحتوي على (الترم الأول والترم الثاني)</span>
            <button class="card-btn">استعراض الترمات <i class="fa-solid fa-arrow-left"></i></button>
        `;
        card.addEventListener('click', () => {
            selectedLevel = lvl;
            currentView = 'terms';
            renderApp();
        });
        grid.appendChild(card);
    });
}

// 4. عرض الأترم (الترم الأول والترم الثاني)
function renderTermsView(lvl) {
    appContainer.innerHTML = `
        <div class="section-header">
            <h2>${lvl.name} - مكتبة الملازم والكتب</h2>
            <p>اختر الفصل الدراسي (الترم) لعرض المحتوى العلمي</p>
        </div>
        <div class="cards-grid" id="gridContent"></div>
    `;
    const grid = document.getElementById('gridContent');
    lvl.terms.forEach(term => {
        const card = document.createElement('div');
        card.className = 'interactive-card';
        card.innerHTML = `
            <div class="card-icon"><i class="fa-solid fa-folder-open"></i></div>
            <h3>${term.name}</h3>
            <span>${term.books.length} كتب وملازم متوفرة للتحميل</span>
            <button class="card-btn">فتح مكتبة الترم <i class="fa-solid fa-arrow-left"></i></button>
        `;
        card.addEventListener('click', () => {
            selectedTerm = term;
            currentView = 'books';
            renderApp();
        });
        grid.appendChild(card);
    });
}

// 5. عرض الكتب والملازم النهائية
function renderBooksView(term) {
    appContainer.innerHTML = `
        <div class="section-header">
            <h2>مكتبة المواد الدراسية والملازم</h2>
            <p>قائمة الكتب والمراجع العلمية والملازم المعتمدة</p>
        </div>
        <div class="library-container" id="booksGrid"></div>
    `;
    const grid = document.getElementById('booksGrid');
    term.books.forEach(book => {
        const card = document.createElement('div');
        card.className = 'book-card';
        card.innerHTML = `
            <div class="book-info">
                <h4>${book.title}</h4>
                <p><i class="fa-solid fa-user-pen"></i> المؤلف/المرجع: ${book.author}</p>
                <span class="badge-tag">${book.type}</span>
            </div>
            <div class="book-actions">
                <button class="btn-action btn-view" onclick="alert('جاري فتح معاينة الكتاب: ${book.title}')"><i class="fa-solid fa-eye"></i> معاينة</button>
                <button class="btn-action btn-download" onclick="alert('جاري بدء تحميل الملف لـ: ${book.title}')"><i class="fa-solid fa-download"></i> تحميل</button>
            </div>
        `;
        grid.appendChild(card);
    });
}

// تحديث شريط المسار (Breadcrumb)
function updateBreadcrumb() {
    let html = `<span onclick="goToStep('faculties')"><i class="fa-solid fa-house"></i> الرئيسية</span>`;
    if (currentView !== 'faculties' && selectedFaculty) {
        html += ` / <span onclick="goToStep('departments')">${selectedFaculty.name}</span>`;
    }
    if ((currentView === 'levels' || currentView === 'terms' || currentView === 'books') && selectedDepartment) {
        html += ` / <span onclick="goToStep('levels')">${selectedDepartment.name}</span>`;
    }
    if ((currentView === 'terms' || currentView === 'books') && selectedLevel) {
        html += ` / <span onclick="goToStep('terms')">${selectedLevel.name}</span>`;
    }
    if (currentView === 'books' && selectedTerm) {
        html += ` / <span class="active-path">${selectedTerm.name}</span>`;
    }
    breadcrumbBar.innerHTML = html;
}

// التنقل العكسي عبر الـ Breadcrumb
window.goToStep = function(step) {
    currentView = step;
    renderApp();
};

// البحث الفوري
globalSearch.addEventListener('input', (e) => {
    const query = e.target.value.toLowerCase().trim();
    if (!query) {
        if (currentView === 'faculties') renderFacultiesView(universityDatabase);
        return;
    }
    if (currentView === 'faculties') {
        const filtered = universityDatabase.filter(f => f.name.toLowerCase().includes(query) || f.departments.some(d => d.name.toLowerCase().includes(query)));
        renderFacultiesView(filtered);
    }
});

// تبديل الوضع الليلي
themeToggle.addEventListener('click', () => {
    const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    if (isDark) {
        document.documentElement.removeAttribute('data-theme');
        themeToggle.innerHTML = '<i class="fa-solid fa-moon"></i>';
        localStorage.setItem('uni_theme', 'light');
    } else {
        document.documentElement.setAttribute('data-theme', 'dark');
        themeToggle.innerHTML = '<i class="fa-solid fa-sun"></i>';
        localStorage.setItem('uni_theme', 'dark');
    }
});

if (localStorage.getItem('uni_theme') === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
    themeToggle.innerHTML = '<i class="fa-solid fa-sun"></i>';
}

// البدء عند التشغيل
renderApp();